using EqlTracker.Core;

internal static class PetWorkspaceTests
{
    internal static void Register(Action<string,Action> test)
    {
        void T(string name,Action run)=>test("Pet workspace: "+name,run);
        T("edits are isolated and Undo restores the complete baseline",()=>{var b=Build();var before=PetWorkspaceDraft.Key(b);var d=new PetWorkspaceDraft(b);d.Working.Items[0].Rank=8;d.Working.DualWield=false;d.Working.Focus="Test";d.Working.SlotConfigurations[0].Effects[0].Effect="Changed";Check(d.Dirty&&PetWorkspaceDraft.Key(b)==before);d.Undo();Check(!d.Dirty&&PetWorkspaceDraft.Key(d.Working)==before);});
        T("commit establishes a new baseline",()=>{var b=Build();var d=new PetWorkspaceDraft(b);d.Working.Items[0].Rank=7;var committed=d.Commit();Check(!d.Dirty&&committed.Items[0].Rank==7);committed.Items[0].Rank=3;Check(d.Working.Items[0].Rank==7);});
        T("timestamps history and derived level are not edits",()=>{var d=new PetWorkspaceDraft(Build());d.Working.Items[0].ConfirmedAt=DateTime.Now;d.Working.LevelEvidence="Refreshed";d.Working.PetLevel=49;PetBuildEditing.Remember(d.Working,"bookkeeping");Check(!d.Dirty);});
        T("concurrent saved changes block commit",()=>{var b=Build();var d=new PetWorkspaceDraft(b);d.Working.Items[0].Rank=8;b.Items[0].Rank=5;Check(!d.CanCommit(b)&&d.Dirty&&d.Working.Items[0].Rank==8);});
        T("followed detection does not dirty or conflict",()=>{var b=Build();b.FollowDetectedSummon=true;var d=new PetWorkspaceDraft(b,false,true);b.PetType="Air";b.SummonSpell="Air X";b.SummonRank=10;d.Follow(b);Check(!d.Dirty&&d.CanCommit(b)&&d.Working.PetType=="Air");d.Working.FollowDetectedSummon=false;d.Working.PetType="Water";d.Follow(b);Check(d.Dirty&&d.Working.PetType=="Water");});
        T("new plans are drafts and saved plans stay independent",()=>{var b=Build();var d=new PetWorkspaceDraft(b,true);Check(d.Dirty&&d.CanCommit(null)&&!d.CanCommit(b));d.Commit();Check(!d.Dirty);});
        T("fixed hands reject armor and misplaced weapons",()=>{var b=Build();var c=Catalog();Check(PetPositionEditing.Validate(b,c.Items[2],1,7).Length>0&&PetPositionEditing.Validate(b,c.Items[0],3,7).Length>0&&PetPositionEditing.Validate(b,c.Items[1],2,7)=="");});
        T("occupied replacement stays at its target and retains Exaltations",()=>{var b=Build();var c=Catalog();string effect=b.SlotConfigurations[0].Effects[0].Effect;Check(PetPositionEditing.Replace(b,c.Items[1],new(){Name="Second sword +9"},1,7,out _));Check(b.Items.Count==2&&b.Items.Single(i=>i.Position==1).Rank==9&&b.Items.Single(i=>i.Position==1).ItemKey=="second"&&b.Items.Single(i=>i.Position==1).Exaltations[0].Effect==effect&&b.Items.Single(i=>i.Position==1).Exaltations[0].State=="Planned");});
        T("swap carries item identity and rank but leaves position effects",()=>{var b=Build();var c=Catalog();string first=b.Items[0].Id;Check(PetPositionEditing.Swap(b,first,2,c,7,out _));var moved=b.Items.Single(i=>i.Id==first);Check(moved.Position==2&&moved.Rank==4&&moved.Exaltations.Single().Effect=="Second focus"&&b.Items.Single(i=>i.Position==1).Exaltations.Single().Effect=="First proc");});
        T("same position and rejected moves are no-ops",()=>{var d=new PetWorkspaceDraft(Build());var c=Catalog();Check(PetPositionEditing.Swap(d.Working,"a",1,c,7,out _)&&!d.Dirty);Check(!PetPositionEditing.Swap(d.Working,"a",3,c,7,out _)&&!d.Dirty);});
        T("removal preserves the empty position configuration",()=>{var b=Build();Check(PetPositionEditing.Remove(b,"a")&&b.Items.All(i=>i.Position!=1)&&b.SlotConfigurations.Single(s=>s.Position==1).Effects.Count==1);});
        T("retained legacy conflicts survive replacement for review",()=>{var b=Build();b.SlotConfigurations[0].Effects.Add(new(){SocketType="Proc",Effect="Second proc"});Check(PetPositionEditing.Replace(b,Catalog().Items[1],null,1,7,out _)&&b.SlotConfigurations[0].Effects.Count==2&&PetEffectPolicy.Conflicts(b.Items.Single(i=>i.Position==1).Exaltations).Contains("Proc"));});
        T("recorded ranks above twenty survive drafts",()=>{var b=Build();b.Items[0].Rank=27;var d=new PetWorkspaceDraft(b);d.Working.Focus="Test";Check(d.Commit().Items[0].Rank==27);});
        T("zone aliases and multiple roots use documented connections",()=>{var c=Catalog();var index=new ProgressBrowseIndex(c);var rows=index.Choices(ProgressBrowseMode.Zone,new(),new(),false,"Lake Rathe");Check(rows.Count==1&&rows[0].Quests.Count==2&&rows[0].ZoneKey==Identity.ZoneKey("Lake Rathetear"));});
        T("zone search covers linked items and full trees remain available",()=>{var c=Catalog();var i=new ProgressBrowseIndex(c);var row=i.Choices(ProgressBrowseMode.Zone,new(),new(),false,"First sword").Single();Check(row.Quests.Count==2&&i.IsZone(new(){ItemKeys=["first"]},row.ZoneKey));Check(i.Choices(ProgressBrowseMode.Zone,new(),new(),false,"absent").Count==0);});
        T("zone browsing does not change tracking Queue routes or completion",()=>{var p=new CharacterProfile();var before=PetComparisonEngine.Key(p);new ProgressBrowseIndex(Catalog()).Choices(ProgressBrowseMode.Zone,p,new(),false,"");Check(before==PetComparisonEngine.Key(p));});
    }
    private static void Check(bool condition){if(!condition)throw new InvalidOperationException("Pet workspace assertion failed");}
    private static PetBuild Build()=>new(){Id="build",Name="Current",PetType="Earth",LevelMode=PetLevelMode.Automatic,PetLevel=50,DualWield=true,SlotConfigurationVersion=1,Items=[new(){Id="a",Position=1,ItemKey="first",Name="First sword",Rank=4,Slot="Primary",Exaltations=[new(){SocketType="Proc",Effect="First proc"}]},new(){Id="b",Position=2,ItemKey="second",Name="Second sword",Rank=5,Slot="Secondary",Exaltations=[new(){SocketType="Focus",Effect="Second focus"}]}],SlotConfigurations=[new(){Position=1,ObservedItemId="a",Effects=[new(){SocketType="Proc",Effect="First proc"}]},new(){Position=2,ObservedItemId="b",Effects=[new(){SocketType="Focus",Effect="Second focus"}]}]};
    private static Catalog Catalog()=>new(){Items=[new(){Key="first",Name="First sword",Slots=["Primary","Secondary"],Sources=[new(){Zone="Lake Rathetear",Mob="Guardian"}]},new(){Key="second",Name="Second sword",Slots=["Primary","Secondary"]},new(){Key="armor",Name="Armor",Slots=["Chest"]}],Quests=[new(){Id="one",Name="First quest",Requirements=[new(){ItemKey="first"}],Steps=[new(){Id="offsite",Instructions="Travel elsewhere"}]},new(){Id="two",Name="Second quest",StartZone="Lake Rathetear",RewardKey="first"}]};
}
